import{_ as t,o as e,c as n,a2 as s}from"./chunks/framework.RycU2wFZ.js";const g=JSON.parse('{"title":"AgentFinOps 官方开发与技术架构文档 🚀","description":"","frontmatter":{},"headers":[],"relativePath":"index.md","filePath":"index.md"}'),l={name:"index.md"};function i(o,a,r,d,p,c){return e(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="agentfinops-官方开发与技术架构文档-🚀" tabindex="-1">AgentFinOps 官方开发与技术架构文档 🚀 <a class="header-anchor" href="#agentfinops-官方开发与技术架构文档-🚀" aria-label="Permalink to &quot;AgentFinOps 官方开发与技术架构文档 🚀&quot;">​</a></h1><blockquote><p><strong>定位</strong>：企业级 AI 行为审计与资金防火墙网关 (AI Agent Gateway &amp; FinOps)<br><strong>核心使命</strong>：为政企与生产级 AI Agent 提供金融级安全防火墙、组织树状配额切分、人在回路 (HITL) 审批与不可篡改审计<br><strong>官方主线基线</strong>：对齐 Master Roadmap v2.0.0 架构规范</p></blockquote><hr><h2 id="平台愿景与核心壁垒-vision-moat" tabindex="-1">平台愿景与核心壁垒 (Vision &amp; Moat) <a class="header-anchor" href="#平台愿景与核心壁垒-vision-moat" aria-label="Permalink to &quot;平台愿景与核心壁垒 (Vision &amp; Moat)&quot;">​</a></h2><p>在企业级大模型与智能体规模化落地过程中，底层的支付与结算通道（微信支付、支付宝、企业对公转账、银企直联）是可插拔的基础设施。AgentPay / AgentFinOps 最核心且不可替代的壁垒在于：</p><blockquote><p><strong>架设在“AI 智能与推理”与“外部资金与数据资源”之间的「金融防火墙（Financial Firewall）」、「防悬挂三态状态机（Hold/Capture/Release）」以及「不可篡改行为审计黑匣子」。</strong></p></blockquote><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                               ┌────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>                               │     AgentPay: 企业级 AI 行为审计与资金防火墙网关 (FinOps) │</span></span>
<span class="line"><span>                               └───────────────────────────┬────────────────────────────┘</span></span>
<span class="line"><span>              ┌────────────────────────────┬───────────────┴───────────────┬────────────────────────────┐</span></span>
<span class="line"><span>              ▼                            ▼                               ▼                            ▼</span></span>
<span class="line"><span>     【模块一：企业内控与安全】      【模块二：FinOps与财务闭环】    【模块三：微计费与高并发清算】   【模块四：生态与全栈开发】</span></span>
<span class="line"><span>     • 飞书/企微/钉钉 HITL 审批      • 租户/部门/项目树状预算切分      • 毫秒级 Token 流式微计费       • MCP 协议原生支付中间件</span></span>
<span class="line"><span>     • 独立进程外 Sidecar 防御       • 微信/支付宝企业预付充值        • 高频批量记账缓冲与聚合落盘     • 与 Langfuse 深度联动共生</span></span>
<span class="line"><span>     • 云端 KMS / 国密 HSM 硬件签名  • 严防“二清”持牌合规分账         • 分布式集群与多节点一致性       • Java/Spring Boot Starter</span></span>
<span class="line"><span>     • 行为异动实时检测与自适应熔断  • 数电发票与对账单流水导出       • 五重对账巡检与自动平账调度     • 推进行业行为审计协议标准</span></span></code></pre></div><hr><h2 id="核心产品定位与企业价值" tabindex="-1">核心产品定位与企业价值 <a class="header-anchor" href="#核心产品定位与企业价值" aria-label="Permalink to &quot;核心产品定位与企业价值&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;"><strong>企业级 AI 行为审计与资金防火墙 (Enterprise FinOps Gateway)</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心定位</strong></td><td style="text-align:left;"><strong>AI Agent Gateway &amp; FinOps Financial Firewall</strong></td></tr><tr><td style="text-align:left;"><strong>主要客群</strong></td><td style="text-align:left;">接入生产环境的政企客户、Agent 开发者、SaaS 服务商、企业内部 IT 与财务平台</td></tr><tr><td style="text-align:left;"><strong>解决痛点</strong></td><td style="text-align:left;">预防 Agent 死循环刷爆预算、财务分摊一团烂账、合规审计定责困难、失控调用造成资产损失</td></tr><tr><td style="text-align:left;"><strong>资金通道</strong></td><td style="text-align:left;">人民币预付虚拟账本（6 位微单位）、企业对公汇款凭证审核、微信支付/支付宝对接、数电发票直连</td></tr></tbody></table><hr><h2 id="核心技术特性" tabindex="-1">核心技术特性 <a class="header-anchor" href="#核心技术特性" aria-label="Permalink to &quot;核心技术特性&quot;">​</a></h2><ul><li>⚡ <strong>反向代理与微支付网关</strong>：基于 Go 语言构建的极速网关，流式解析 LLM 响应，原生支持 HTTP 402 协议握手与挑战重放。</li><li>🛡️ <strong>秒级防死循环熔断</strong>：滑动窗口 RPM 监控，当智能体发生非受控递归或 Prompt 注入攻击时，毫秒级掐断网络出入口，杜绝天价账单。</li><li>📱 <strong>办公协同人在回路 (HITL)</strong>：单笔调用超过阈值时，网关返回 402 异步挂起，自动向负责人的<strong>飞书 / 企业微信 / 钉钉</strong>推送富文本审批卡片，移动端一键授权放行。</li><li>🏢 <strong>四级树状多层预算切分</strong>：<strong>租户 $\\to$ 事业群/部门 $\\to$ 项目组 $\\to$ 具体 Agent</strong>，支持父节点总预算硬顶 + 子节点月度配额划拨与级联约束。</li><li>⚖️ <strong>防悬挂三态状态机</strong>：严格遵循 <code>Hold</code>（事前冻结）$\\to$ <code>Capture</code>（事后确认扣费）$\\to$ <code>Release</code>（未消耗额度原子返还），极端异常永不发生悬挂扣款。</li><li>📊 <strong>不可篡改行为黑匣子</strong>：全链路审计时间线，记录 Agent 的每一次 Tool Call 入参、响应耗时、Session ID 与扣款凭单，符合等保 2.0 规范。</li><li>🤝 <strong>与 Langfuse 联合共生</strong>：Langfuse 管“大脑”（Prompt 调试与评估），AgentPay 管“双手”（金钱拦截与物理熔断），Trace ID 跨服务无缝透传。</li><li>🔌 <strong>MCP 协议原生集成</strong>：为 Anthropic MCP Server 提供标价插件，为 MCP Client 提供端侧金融防火墙。</li></ul><hr><h2 id="快速导航" tabindex="-1">快速导航 <a class="header-anchor" href="#快速导航" aria-label="Permalink to &quot;快速导航&quot;">​</a></h2><h3 id="_1-战略规划与架构决策" tabindex="-1">1. 战略规划与架构决策 <a class="header-anchor" href="#_1-战略规划与架构决策" aria-label="Permalink to &quot;1. 战略规划与架构决策&quot;">​</a></h3><ul><li><a href="/docs/roadmap/">核心任务全景规划与技术演进路线图 (Master Roadmap v2.0.0)</a></li><li><a href="/docs/roadmap/execution-plan">Master 落地实施计划与 Phase 1 (P0) 执行分解</a></li><li><a href="/docs/architecture/">系统全景架构与系统拓扑规范</a></li><li><a href="/docs/architecture/security-model">企业安全与 N1-N6 威胁模型</a></li><li><a href="/docs/architecture/adr-001">ADR-001: x402 协议架构决策</a></li></ul><h3 id="_2-finops-成本治理与合规财务" tabindex="-1">2. FinOps 成本治理与合规财务 <a class="header-anchor" href="#_2-finops-成本治理与合规财务" aria-label="Permalink to &quot;2. FinOps 成本治理与合规财务&quot;">​</a></h3><ul><li><a href="/docs/finops/">企业级 AI 行为审计与资金防火墙战术框架</a></li><li><a href="/docs/finops/budget-control">树状组织多层配额模型与预算控制体系</a></li><li><a href="/docs/finops/wallet-ledger">内部虚拟钱包与只追加不可变账本</a></li><li><a href="/docs/finops/fiat-topup">国内合规法币充值与防“二清”机制</a></li></ul><h3 id="_3-企业协同与人在回路-hitl" tabindex="-1">3. 企业协同与人在回路 (HITL) <a class="header-anchor" href="#_3-企业协同与人在回路-hitl" aria-label="Permalink to &quot;3. 企业协同与人在回路 (HITL)&quot;">​</a></h3><ul><li><a href="/docs/security-hitl/hitl-approval">办公协同与人在回路 (HITL) 审批规范（飞书/企微/钉钉）</a></li><li><a href="/docs/security-hitl/agent-audit">Agent 身份黑匣子与不可篡改行为审计流</a></li><li><a href="/docs/security-hitl/audit-events">消费与操作审计事件契约规范</a></li></ul><h3 id="_4-核心微支付协议与模型" tabindex="-1">4. 核心微支付协议与模型 <a class="header-anchor" href="#_4-核心微支付协议与模型" aria-label="Permalink to &quot;4. 核心微支付协议与模型&quot;">​</a></h3><ul><li><a href="/docs/protocol/state-machine">防悬挂三态状态机规范 (Hold / Capture / Release)</a></li><li><a href="/docs/protocol/consistency">跨语言协议一致性规范与统一错误码表</a></li><li><a href="/docs/protocol/config-publishing">动态路由策略发布与 RCU 原子生效规范</a></li></ul><h3 id="_5-开放生态与开发者接入" tabindex="-1">5. 开放生态与开发者接入 <a class="header-anchor" href="#_5-开放生态与开发者接入" aria-label="Permalink to &quot;5. 开放生态与开发者接入&quot;">​</a></h3><ul><li><a href="/docs/ecosystem/mcp-plugin">MCP (Model Context Protocol) 协议原生支付中间件与防火墙</a></li><li><a href="/docs/ecosystem/langfuse">与 Langfuse 深度共生：打造企业级 AI 运维双子星</a></li><li><a href="/docs/guide/sdk_quickstart">客户端 SDK 接入指南 (Python &amp; TypeScript)</a></li><li><a href="/docs/guide/console_guide">企业管理控制台操作指南</a></li><li><a href="/docs/deployment/quickstart">快速安装与 Docker Compose 部署</a></li></ul>`,25)])])}const u=t(l,[["render",i]]);export{g as __pageData,u as default};
